  sessionTtlSeconds?: number;
  /** Admin console credentials (in-app login, PRD §57). */
  adminUser?: string;
  adminPassword?: string;
  /** Set-Cookie Secure flag; default true (behind HTTPS). Set false for local http. */
  cookieSecure?: boolean;
  /** Directory of the built admin SPA. Default: packages/admin-web/dist. */
  adminDist?: string;
  /** Test-only: skip the admin auth gate. Never set in production bootstrap. */
  authDisabled?: boolean;
  /** Fastify request logging; default on. Tests pass false. */
  logger?: boolean;
}

const SOURCE_EXTENSIONS = new Set(["mp4", "mov", "m4v", "mpg", "mpeg", "ts", "mkv", "webm"]);
export const DEV_SESSION_SECRET = "dev-insecure-session-secret";

function safeEqual(a: string, b: string): boolean {
  const ab = Buffer.from(a);
  const bb = Buffer.from(b);
  return ab.length === bb.length && timingSafeEqual(ab, bb);
}

export function buildServer(deps: ServerDeps) {
  const app = Fastify({ logger: deps.logger ?? true });
  const { pool, podCache, store } = deps;
  const dataPlaneUrl = deps.dataPlaneUrl ?? process.env.DATA_PLANE_PUBLIC_URL ?? "http://localhost:4010";
  const sessionSecret = deps.sessionSecret ?? process.env.SESSION_SIGNING_SECRET ?? DEV_SESSION_SECRET;
  const sessionTtlSeconds = deps.sessionTtlSeconds ?? Number(process.env.SESSION_TTL_SECONDS ?? 86400);
  const adminUser = deps.adminUser ?? process.env.ADMIN_USER ?? "ops";
  const adminPassword = deps.adminPassword ?? process.env.ADMIN_PASSWORD ?? "";
  const cookieSecure = deps.cookieSecure ?? (process.env.COOKIE_SECURE ?? "true") !== "false";
  const adminDist = deps.adminDist ?? fileURLToPath(new URL("../../admin-web/dist", import.meta.url));

