    const b = (req.body ?? {}) as Record<string, unknown>;
    await campaignsRepo.insertCampaign(pool, {
      id,
      advertiser: (b.advertiser as string) ?? existing.advertiser,
      startDate: (b.start_date as string) ?? existing.startDate,
      endDate: (b.end_date as string) ?? existing.endDate,
      status: (b.status as Campaign["status"]) ?? existing.status,
